def _lcs_zincir(a: list[str], b: list[str]) -> list[tuple[int, int]]:
    """a, b için LCS zinciri: (a_endeksi, b_endeksi) çiftleri, her iki
    dizide artan sırada. O(n*m) süre ve bellek."""
    n = len(a)
    m = len(b)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        s = a[i]
        row = dp[i]
        row_next = dp[i + 1]
        for j in range(m - 1, -1, -1):
            if s == b[j]:
                row[j] = row_next[j + 1] + 1
            else:
                row[j] = row_next[j] if row_next[j] >= row[j + 1] else row[j + 1]
    zincir: list[tuple[int, int]] = []
    i = j = 0
    while i < n and j < m:
        if a[i] == b[j]:
            zincir.append((i, j))
            i += 1
            j += 1
        elif dp[i + 1][j] >= dp[i][j + 1]:
            i += 1
        else:
            j += 1
    return zincir

